CREATE EXTENSION IF NOT EXISTS "uuid-ossp";CREATE TABLE users (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),email VARCHAR(255) UNIQUE NOT NULL,hashed_password VARCHAR(255) NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());CREATE TYPE transaction_type AS ENUM ('income', 'expense');CREATE TABLE categories (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(255) NOT NULL,type transaction_type NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),UNIQUE (user_id, name, type));CREATE TABLE transactions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,category_id UUID NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,type transaction_type NOT NULL,amount NUMERIC(15, 2) NOT NULL,description TEXT,transaction_date DATE NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());CREATE INDEX idx_transactions_user_id ON transactions (user_id);CREATE INDEX idx_transactions_transaction_date ON transactions (transaction_date);CREATE INDEX idx_categories_user_id ON categories (user_id);